#!/usr/bin/env perl
use strict;
use warnings;
use File::Find;
use File::Basename;

my $ROOT = '/bench/repo';
my $MODULE = 'github.com/usememos/memos';

my @all_go_files;
my %file_content;
my %file_pkg;
my %file_imports;
my %file_dir_pkg;

find(
    sub {
        return unless /\.go$/;
        my $path = $File::Find::name;
        push @all_go_files, $path;
        open my $fh, '<', $path or die "Cannot read $path: $!";
        local $/;
        my $content = <$fh>;
        close $fh;
        $file_content{$path} = $content;

        if ($content =~ /^package\s+(\w+)/m) {
            $file_pkg{$path} = $1;
            my $dir = dirname($path);
            $file_dir_pkg{$dir} = $1 unless $path =~ /_test\.go$/;
        }

        $file_imports{$path} = parse_imports($content);
    },
    $ROOT
);

sub parse_imports {
    my ($content) = @_;
    my %imports;
    while ($content =~ /import\s+(?:\(\s*([\s\S]*?)\s*\)|"([^"]+)")/g) {
        my $block = $1 // $2;
        next unless defined $block;
        for my $line (split /\n/, $block) {
            $line =~ s/\/\/.*$//;
            next if $line =~ /^\s*$/;
            if ($line =~ /^\s*(?:(\w+)\s+)?"([^"]+)"/) {
                my ($alias, $path) = ($1, $2);
                $alias //= (split /\//, $path)[-1];
                $alias =~ s/^\.//;
                next if $alias eq '.';
                $imports{$alias} = $path;
            }
        }
    }
    return \%imports;
}

my %internal_decls;
my %internal_dirs;

for my $path (sort @all_go_files) {
    next unless $path =~ m{^\Q$ROOT\E/internal/};
    next if $path =~ /_test\.go$/;

    my $content = $file_content{$path};
    my $pkg = $file_pkg{$path} // next;
    my $dir = dirname($path);

    my $rel = $path;
    $rel =~ s/^\Q$ROOT\E\/?//;
    my @parts = split m{/}, $rel;
    pop @parts;
    my $import_path = $MODULE . '/' . join('/', @parts);
    $internal_dirs{$import_path} = "$ROOT/" . join('/', @parts);

    my @lines = split /\n/, $content;
    for my $i (0 .. $#lines) {
        my $line = $lines[$i];
        next unless $line =~ /^func\s+(?:\(([^)]*)\)\s+)?(\w+)\s*\(/;
        my ($recv, $name) = ($1 // '', $2);
        next if $name eq 'init';
        my $exported = ($name =~ /^[A-Z]/) ? 1 : 0;
        my $recv_type = '';
        if ($recv ne '') {
            $recv =~ s/^\*//;
            $recv =~ s/^(\w+)\s+\*/$1/;
            ($recv_type) = $recv =~ /(\w+)\s*$/;
        }
        my $sym_id = make_sym_id($import_path, $recv_type, $name);
        $internal_decls{$sym_id} = {
            path         => $path,
            line         => $i + 1,
            name         => $name,
            recv         => $recv_type,
            pkg          => $pkg,
            import_path  => $import_path,
            dir          => $dir,
            exported     => $exported,
        };
    }
}

sub make_sym_id {
    my ($import_path, $recv, $name) = @_;
    return $recv ? "$import_path|(*$recv).$name" : "$import_path|$name";
}

my %file_funcs;

for my $path (@all_go_files) {
    my @lines = split /\n/, $file_content{$path};
    my @stack;
    for my $i (0 .. $#lines) {
        if ($lines[$i] =~ /^func\s+(?:\([^)]*\)\s+)?(\w+)\s*\(/) {
            push @stack, { name => $1, start => $i + 1 };
        }
        if ($lines[$i] =~ /^}/ && @stack) {
            my $f = pop @stack;
            $f->{end} = $i + 1;
            push @{ $file_funcs{$path} }, $f;
        }
    }
}

sub caller_at {
    my ($path, $line) = @_;
    for my $f (@{ $file_funcs{$path} // [] }) {
        return $f->{name} if $line >= $f->{start} && $line <= ($f->{end} // $line);
    }
    return '<toplevel>';
}

my %path_to_decls;
for my $sid (keys %internal_decls) {
    my $ip = $internal_decls{$sid}{import_path};
    push @{ $path_to_decls{$ip} }, $sid;
}

my %dir_decls;
for my $sid (keys %internal_decls) {
    push @{ $dir_decls{ $internal_decls{$sid}{dir} } }, $sid;
}

my %callsites;
my %callers;

for my $path (@all_go_files) {
    my $content = $file_content{$path};
    my $imports = $file_imports{$path};
    my @lines = split /\n/, $content;
    my $cur_dir = dirname($path);

    for my $i (0 .. $#lines) {
        my $line = $lines[$i];
        my $ln = $i + 1;
        my $caller = caller_at($path, $ln);

        next if $line =~ /^func\s+/;

        my $code = $line;
        $code =~ s/`[^`]*`//g;
        $code =~ s/"([^"\\]|\\.)*"//g;
        $code =~ s/\/\/.*$//;

        while ($code =~ /\b([A-Za-z_]\w*)\.([A-Za-z_]\w*)\s*\(/g) {
            my ($alias, $fname) = ($1, $2);
            next if is_go_keyword($alias) || is_go_keyword($fname);
            next if is_builtin_pkg($alias);
            my $ip = $imports->{$alias};
            next unless defined $ip && $ip =~ m{^$MODULE/internal/};
            record_call($ip, '', $fname, $path, $ln, $caller);
        }

        while ($code =~ /\.([A-Za-z_]\w*)\s*\(/g) {
            my ($mname) = ($1);
            next if is_go_keyword($mname);
            for my $sid (keys %internal_decls) {
                my $d = $internal_decls{$sid};
                next unless $d->{recv} ne '' && $d->{name} eq $mname;
                if ($path =~ m{^\Q$d->{path}\E$} || same_package($path, $d->{dir})) {
                    record_sid($sid, $path, $ln, $caller);
                }
                elsif (imports_path($imports, $d->{import_path})) {
                    record_sid($sid, $path, $ln, $caller);
                }
            }
        }

        while ($code =~ /(?:^|[^\w.])([A-Za-z_]\w*)\s*\(/g) {
            my ($fname) = ($1);
            next if is_go_keyword($fname) || is_go_builtin($fname);
            next if $fname =~ /^[a-z]/;

            if (exists $dir_decls{$cur_dir}) {
                for my $sid (@{ $dir_decls{$cur_dir} }) {
                    my $d = $internal_decls{$sid};
                    next if $d->{recv} ne '';
                    next unless $d->{name} eq $fname;
                    record_sid($sid, $path, $ln, $caller);
                }
            }

            for my $alias (keys %$imports) {
                my $ip = $imports->{$alias};
                next unless $ip =~ m{^$MODULE/internal/};
                my $sid = make_sym_id($ip, '', $fname);
                record_sid($sid, $path, $ln, $caller) if exists $internal_decls{$sid};
            }
        }
    }
}

sub record_call {
    my ($import_path, $recv, $fname, $path, $ln, $caller) = @_;
    my $sid = make_sym_id($import_path, $recv, $fname);
    record_sid($sid, $path, $ln, $caller) if exists $internal_decls{$sid};
}

sub record_sid {
    my ($sid, $path, $ln, $caller) = @_;
    return unless exists $internal_decls{$sid};
    $callsites{$sid}{"$path:$ln"} = 1;
    $callers{$sid}{"$path::$caller"} = 1;
}

sub same_package {
    my ($file, $dir) = @_;
    return dirname($file) eq $dir;
}

sub imports_path {
    my ($imports, $target) = @_;
    for my $ip (values %$imports) {
        return 1 if $ip eq $target;
    }
    return 0;
}

sub is_go_keyword {
    my ($w) = @_;
    return $w =~ /^(break|case|chan|const|continue|default|defer|else|fallthrough|for|func|go|goto|if|import|interface|map|package|range|return|select|struct|switch|type|var)$/;
}

sub is_go_builtin {
    my ($w) = @_;
    return $w =~ /^(append|cap|close|complex|copy|delete|imag|len|make|new|panic|print|println|real|recover)$/;
}

sub is_builtin_pkg {
    my ($w) = @_;
    return $w =~ /^(fmt|strings|strconv|errors|context|time|io|os|log|sync|sort|bytes|encoding|json|http|url|path|filepath|reflect|runtime|math|crypto|net|sql|template|html|xml|regexp|unicode|bufio|slices|maps|cmp|iter|testing)$/;
}

my @ranked = sort {
    (scalar(keys %{ $callers{$b} // {} }) <=> scalar(keys %{ $callers{$a} // {} }))
      || (scalar(keys %{ $callsites{$b} // {} }) <=> scalar(keys %{ $callsites{$a} // {} }))
} keys %internal_decls;

print "=== INTERNAL DECLARATIONS: ", scalar(keys %internal_decls), " ===\n\n";
print "=== TOP 30 BY DISTINCT CALLING FUNCTIONS (fan-in) ===\n";
my $n = 0;
for my $sid (@ranked) {
    my $d = $internal_decls{$sid};
    my $nc = scalar(keys %{ $callers{$sid} // {} });
    my $ns = scalar(keys %{ $callsites{$sid} // {} });
    next if $nc == 0 && $ns == 0;
    $n++;
    last if $n > 30;
    my $sym = $d->{recv} ? "(*$d->{recv}).$d->{name}" : $d->{name};
    printf "%3d. %-45s callers=%4d  callsites=%4d\n", $n, $sym, $nc, $ns;
    printf "     %s:%d  [%s]\n", $d->{path}, $d->{line}, $d->{import_path};
}

print "\n=== TOP 30 BY CALL SITES ===\n";
@ranked = sort {
    (scalar(keys %{ $callsites{$b} // {} }) <=> scalar(keys %{ $callsites{$a} // {} }))
      || (scalar(keys %{ $callers{$b} // {} }) <=> scalar(keys %{ $callers{$a} // {} }))
} keys %internal_decls;

$n = 0;
for my $sid (@ranked) {
    my $d = $internal_decls{$sid};
    my $nc = scalar(keys %{ $callers{$sid} // {} });
    my $ns = scalar(keys %{ $callsites{$sid} // {} });
    next if $nc == 0 && $ns == 0;
    $n++;
    last if $n > 30;
    my $sym = $d->{recv} ? "(*$d->{recv}).$d->{name}" : $d->{name};
    printf "%3d. %-45s callsites=%4d  callers=%4d\n", $n, $sym, $ns, $nc;
    printf "     %s:%d\n", $d->{path}, $d->{line};
}

my @by_callers = sort {
    (scalar(keys %{ $callers{$b} // {} }) <=> scalar(keys %{ $callers{$a} // {} }))
} keys %internal_decls;

if (@by_callers) {
    my $top = $by_callers[0];
    my $d = $internal_decls{$top};
    print "\n=== TOP BY CALLERS DETAIL ===\n";
    print "Symbol: ", ($d->{recv} ? "(*$d->{recv}).$d->{name}" : $d->{name}), "\n";
    print "Path: $d->{path}:$d->{line}\n";
    print "Distinct callers ($\{ scalar(keys %{ $callers{$top} // {} }) \}):\n";
    for my $c (sort keys %{ $callers{$top} // {} }) {
        print "  $c\n";
    }
    print "Call sites:\n";
    for my $s (sort keys %{ $callsites{$top} // {} }) {
        print "  $s\n";
    }
}

