BEGIN {
    root = ENVIRON["ROOT"]
    module = ENVIRON["MODULE"]
    nfiles = 0
}

# --- Pass 1: read all files ---
/^FILE / {
    if (nfiles > 0) finalize_file()
    curfile = substr($0, 6)
    nfiles++
    delete imports
    nimport = 0
    pkg = ""
    content = ""
    line_num = 0
    delete lines
    next
}

/^ENDFILE$/ {
    finalize_file()
    next
}

{
    line_num++
    lines[line_num] = $0
    content = content $0 "\n"
    if (line_num == 1 || pkg == "") {
        if (match($0, /^package ([A-Za-z_][A-Za-z0-9_]*)/, m)) pkg = m[1]
    }
    next
}

function finalize_file(    i, line, in_import, block) {
    # parse imports from content
    delete imports
    nimport = 0
    in_import = 0
    for (i = 1; i <= line_num; i++) {
        line = lines[i]
        if (match(line, /^import[ \t]+\(/)) { in_import = 1; continue }
        if (in_import) {
            if (match(line, /^[ \t]*\)/)) { in_import = 0; continue }
            if (match(line, /"([^"]+)"/, m)) {
                alias = m[1]
                sub(/.*\//, "", alias)
                if (match(line, /^[ \t]*([A-Za-z_][A-Za-z0-9_]*)[ \t]+"/, a)) alias = a[1]
                imports[alias] = m[1]
                nimport++
            }
            continue
        }
        if (match(line, /^import[ \t]+"([^"]+)"/, m)) {
            alias = m[1]; sub(/.*\//, "", alias)
            imports[alias] = m[1]
            nimport++
        }
    }

    file_pkg[curfile] = pkg
    file_dir[curfile] = curfile
    sub(/\/[^\/]+$/, "", file_dir[curfile])

    # store imports
    fkey = curfile
    for (a in imports) {
        fi_import[fkey SUBSEP a] = imports[a]
        fi_nimp[fkey]++
    }

    # extract func declarations in internal/
    if (index(curfile, root "/internal/") == 1 && curfile !~ /_test\.go$/) {
        rel = substr(curfile, length(root) + 2)
        n = split(rel, parts, "/")
        import_path = module
        for (i = 1; i < n; i++) import_path = import_path "/" parts[i]

        for (i = 1; i <= line_num; i++) {
            line = lines[i]
            if (match(line, /^func[ \t]+(?:\(([^)]*)\)[ \t]+)?([A-Za-z_][A-Za-z0-9_]*)[ \t]*\(/, m)) {
                fname = m[2]
                if (fname == "init") continue
                recv = m[1]
                recv_type = ""
                if (recv != "") {
                    gsub(/^\*/, "", recv)
                    if (match(recv, /([A-Za-z_][A-Za-z0-9_]*)[ \t]*$/, rm)) recv_type = rm[1]
                }
                sid = sym_id(import_path, recv_type, fname)
                decl_path[sid] = curfile
                decl_line[sid] = i
                decl_name[sid] = fname
                decl_recv[sid] = recv_type
                decl_ip[sid] = import_path
                decl_dir[sid] = file_dir[curfile]
                ndecl++
                dir_decls[file_dir[curfile] SUBSEP sid] = 1
            }
        }
    }

    # extract caller functions
    depth = 0
    delete fstack
    nfstack = 0
    for (i = 1; i <= line_num; i++) {
        line = lines[i]
        if (match(line, /^func[ \t]+(?:\([^)]*\)[ \t]+)?([A-Za-z_][A-Za-z0-9_]*)[ \t]*\(/, m)) {
            nfstack++
            fstack[nfstack] = m[1]
            fstack_start[nfstack] = i
        }
        # simplistic brace tracking for func end
        if (match(line, /^}/)) {
            if (nfstack > 0) {
                caller_map[curfile SUBSEP i] = fstack[nfstack]  # not used directly
                fstack_end[nfstack] = i
                nfstack--
            }
        }
    }
    # store func ranges per file
    nf = 0
    depth = 0
    for (i = 1; i <= line_num; i++) {
        line = lines[i]
        if (match(line, /^func[ \t]+(?:\([^)]*\)[ \t]+)?([A-Za-z_][A-Za-z0-9_]*)[ \t]*\(/, m)) {
            nf++
            ff_name[curfile SUBSEP nf] = m[1]
            ff_start[curfile SUBSEP nf] = i
            brace = 0
            for (j = i; j <= line_num; j++) {
                ll = lines[j]
                # count braces roughly
                for (k = 1; k <= length(ll); k++) {
                    c = substr(ll, k, 1)
                    if (c == "{") brace++
                    if (c == "}") brace--
                }
                if (j > i && brace <= 0) { ff_end[curfile SUBSEP nf] = j; break }
            }
            if (!( (curfile SUBSEP nf) in ff_end )) ff_end[curfile SUBSEP nf] = line_num
        }
    }
    file_nfunc[curfile] = nf

    # save lines for pass 2
    for (i = 1; i <= line_num; i++) file_line[curfile SUBSEP i] = lines[i]
    file_nlines[curfile] = line_num
    filelist[nfiles] = curfile
}

function sym_id(ip, recv, name,   s) {
    if (recv != "") return ip "|(*" recv ")." name
    return ip "|" name
}

END {
    finalize_file()
    # Pass 2: find calls in all files
    for (fi = 1; fi <= nfiles; fi++) {
        f = filelist[fi]
        cur_dir = file_dir[f]
        nlines = file_nlines[f]
        for (i = 1; i <= nlines; i++) {
            line = file_line[f SUBSEP i]
            if (match(line, /^func[ \t]+/)) continue
            code = line
            gsub(/`[^`]*`/, "", code)
            gsub(/"([^"\\]|\\.)*"/, "", code)
            gsub(/\/\/.*$/, "", code)
            caller = caller_at(f, i)

            # qualified: alias.Func(
            pos = 1
            while (match(substr(code, pos), /\b([A-Za-z_][A-Za-z0-9_]*)\.([A-Za-z_][A-Za-z0-9_]*)[ \t]*\(/, m)) {
                alias = m[1]; fname = m[2]
                start = RSTART + pos - 1
                pos = start + RLENGTH
                if (is_kw(alias) || is_kw(fname) || is_bpkg(alias)) continue
                ip = fi_import[f SUBSEP alias]
                if (ip == "" || index(ip, module "/internal/") != 1) continue
                sid = sym_id(ip, "", fname)
                record(sid, f, i, caller)
            }

            # methods: .Method(
            pos = 1
            tmp = code
            while (match(tmp, /\.([A-Za-z_][A-Za-z0-9_]*)[ \t]*\(/, m)) {
                mname = m[1]
                tmp = substr(tmp, RSTART + RLENGTH)
                if (is_kw(mname)) continue
                for (sid in decl_path) {
                    if (decl_recv[sid] == "" || decl_name[sid] != mname) continue
                    if (same_pkg(f, decl_dir[sid]) || file_imports_path(f, decl_ip[sid])) {
                        record(sid, f, i, caller)
                    }
                }
            }

            # bare exported Func(
            pos = 1
            while (match(substr(code, pos), /(?:^|[^A-Za-z0-9_])([A-Z][A-Za-z0-9_]*)[ \t]*\(/, m)) {
                fname = m[1]
                start = RSTART + pos - 1
                pos = start + RLENGTH
                if (is_kw(fname) || is_builtin(fname)) continue

                # same dir
                for (key in dir_decls) {
                    split(key, kp, SUBSEP)
                    if (kp[1] != cur_dir) continue
                    sid = kp[2]
                    if (decl_recv[sid] != "" || decl_name[sid] != fname) continue
                    record(sid, f, i, caller)
                }
                # imports
                for (a in imports) {
                    ip = fi_import[f SUBSEP a]
                    if (ip == "" || index(ip, module "/internal/") != 1) continue
                    sid = sym_id(ip, "", fname)
                    if (sid in decl_path) record(sid, f, i, caller)
                }
            }
        }
    }

    # rank
    print "=== INTERNAL DECLARATIONS: " ndecl " ==="
    print ""
    print "=== TOP 30 BY DISTINCT CALLING FUNCTIONS ==="
    for (sid in decl_path) {
        nc = 0; ns = 0
        for (k in caller_set) if (index(k, sid SUBSEP) == 1) nc++
        for (k in site_set) if (index(k, sid SUBSEP) == 1) ns++
        if (nc == 0 && ns == 0) continue
        rank_nc[sid] = nc
        rank_ns[sid] = ns
    }
    # bubble top 30
    for (t = 1; t <= 30; t++) {
        best = ""; bestv = -1
        for (sid in rank_nc) {
            if (rank_nc[sid] <= 0) continue
            if (done[sid]) continue
            if (rank_nc[sid] > bestv || (rank_nc[sid] == bestv && rank_ns[sid] > rank_ns[best])) {
