            # qualified: alias.Func(
            pos = 1
            while (match(substr(code, pos), /\b([A-Za-z_][A-Za-z0-9_]*)\.([A-Za-z_][A-Za-z0-9_]*)[ \t]*\(/, m)) {
                alias = m[1]; fname = m[2]
                start = RSTART + pos - 1
                pos = start + RLENGTH
                if (is_kw(alias) || is_kw(fname) || is_bpkg(alias)) continue
                ip = fi_import[f SUBSEP alias]
                if (ip == "" || index(ip, module "/internal/") != 1) continue
                sid = sym_id(ip, "", fname)
                record(sid, f, i, caller)
            }

            # methods: .Method(
            pos = 1
            tmp = code
            while (match(tmp, /\.([A-Za-z_][A-Za-z0-9_]*)[ \t]*\(/, m)) {
                mname = m[1]
                tmp = substr(tmp, RSTART + RLENGTH)
                if (is_kw(mname)) continue
                for (sid in decl_path) {
                    if (decl_recv[sid] == "" || decl_name[sid] != mname) continue
                    if (same_pkg(f, decl_dir[sid]) || file_imports_path(f, decl_ip[sid])) {
                        record(sid, f, i, caller)
                    }
                }
            }

            # bare exported Func(
            pos = 1
            while (match(substr(code, pos), /(?:^|[^A-Za-z0-9_])([A-Z][A-Za-z0-9_]*)[ \t]*\(/, m)) {
                fname = m[1]
                start = RSTART + pos - 1
                pos = start + RLENGTH
                if (is_kw(fname) || is_builtin(fname)) continue

                # same dir
                for (key in dir_decls) {
                    split(key, kp, SUBSEP)
                    if (kp[1] != cur_dir) continue
                    sid = kp[2]
                    if (decl_recv[sid] != "" || decl_name[sid] != fname) continue
                    record(sid, f, i, caller)
                }
                # imports
                for (a in imports) {
                    ip = fi_import[f SUBSEP a]
                    if (ip == "" || index(ip, module "/internal/") != 1) continue
                    sid = sym_id(ip, "", fname)
                    if (sid in decl_path) record(sid, f, i, caller)
                }
            }
        }
    }

    # rank
    print "=== INTERNAL DECLARATIONS: " ndecl " ==="
    print ""
    print "=== TOP 30 BY DISTINCT CALLING FUNCTIONS ==="
    for (sid in decl_path) {
        nc = 0; ns = 0
        for (k in caller_set) if (index(k, sid SUBSEP) == 1) nc++
        for (k in site_set) if (index(k, sid SUBSEP) == 1) ns++
        if (nc == 0 && ns == 0) continue
        rank_nc[sid] = nc
        rank_ns[sid] = ns
    }
    # bubble top 30
    for (t = 1; t <= 30; t++) {
        best = ""; bestv = -1
        for (sid in rank_nc) {
            if (rank_nc[sid] <= 0) continue
            if (done[sid]) continue
            if (rank_nc[sid] > bestv || (rank_nc[sid] == bestv && rank_ns[sid] > rank_ns[best])) {
                best = sid; bestv = rank_nc[sid]
            }
        }
        if (best == "") break
        done[best] = 1
        sym = decl_name[best]
        if (decl_recv[best] != "") sym = "(*" decl_recv[best] ")." sym
        printf "%3d. %-45s callers=%4d  callsites=%4d\n", t, sym, rank_nc[best], rank_ns[best]
        printf "     %s:%d  [%s]\n", decl_path[best], decl_line[best], decl_ip[best]
    }

    print ""
    print "=== TOP 30 BY CALL SITES ==="
    delete done
    for (t = 1; t <= 30; t++) {
        best = ""; bestv = -1
        for (sid in rank_ns) {
            if (rank_ns[sid] <= 0) continue
            if (done[sid]) continue
            if (rank_ns[sid] > bestv || (rank_ns[sid] == bestv && rank_nc[sid] > rank_nc[best])) {
                best = sid; bestv = rank_ns[sid]
            }
        }
        if (best == "") break
        done[best] = 1
        sym = decl_name[best]
        if (decl_recv[best] != "") sym = "(*" decl_recv[best] ")." sym
        printf "%3d. %-45s callsites=%4d  callers=%4d\n", t, sym, rank_ns[best], rank_nc[best]
        printf "     %s:%d\n", decl_path[best], decl_line[best]
    }

    # top detail
    top = ""; topv = -1
    for (sid in rank_nc) if (rank_nc[sid] > topv) { top = sid; topv = rank_nc[sid] }
    if (top != "") {
        sym = decl_name[top]
        if (decl_recv[top] != "") sym = "(*" decl_recv[top] ")." sym
        print ""
        print "=== TOP BY CALLERS DETAIL ==="
        print "Symbol: " sym
        print "Path: " decl_path[top] ":" decl_line[top]
        print "Distinct callers: " rank_nc[top]
        print "Call sites: " rank_ns[top]
        print "Callers:"
        for (k in caller_set) {
            if (index(k, top SUBSEP) != 1) continue
            sub("^" top SUBSEP, "", k)
            print "  " k
        }
        print "Sites:"
        for (k in site_set) {
            if (index(k, top SUBSEP) != 1) continue
            sub("^" top SUBSEP, "", k)
            print "  " k
        }
    }
}

function record(sid, f, ln, caller) {
    if (!(sid in decl_path)) return
    site_set[sid SUBSEP f ":" ln] = 1
    caller_set[sid SUBSEP f "::" caller] = 1
}

function caller_at(f, ln,    j, n) {
    n = file_nfunc[f]
    for (j = 1; j <= n; j++) {
        if (ln >= ff_start[f SUBSEP j] && ln <= ff_end[f SUBSEP j]) return ff_name[f SUBSEP j]
    }
    return "<toplevel>"
}

function same_pkg(f, d) { return file_dir[f] == d }

function file_imports_path(f, target,    a) {
    for (a in imports) {
        ip = fi_import[f SUBSEP a]
        if (ip == target) return 1
    }
    # scan all aliases for this file
    for (k in fi_import) {
        split(k, kp, SUBSEP)
        if (kp[1] != f) continue
        if (fi_import[k] == target) return 1
    }
    return 0
}

function is_kw(w) {
    return w ~ /^(break|case|chan|const|continue|default|defer|else|fallthrough|for|func|go|goto|if|import|interface|map|package|range|return|select|struct|switch|type|var)$/
}

function is_builtin(w) {
    return w ~ /^(append|cap|close|complex|copy|delete|imag|len|make|new|panic|print|println|real|recover)$/
}

function is_bpkg(w) {
    return w ~ /^(fmt|strings|strconv|errors|context|time|io|os|log|sync|sort|bytes|encoding|json|http|url|path|filepath|reflect|runtime|math|crypto|net|sql|template|html|xml|regexp|unicode|bufio|slices|maps|cmp|iter|testing)$/
}

args.streamContent:
BEGIN {
    root = ENVIRON["ROOT"]
    module = ENVIRON["MODULE"]
    nfiles = 0
    ndecl = 0
}

/^FILE / {
    if (nfiles > 0) finalize_file()
    curfile = substr($0, 6)
    nfiles++
    pkg = ""
    line_num = 0
    next
}

/^ENDFILE$/ {
    finalize_file()
    next
}

{
    line_num++
    lines[line_num] = $0
    if (pkg == "" && $0 ~ /^package [A-Za-z_]/) {
        pkg = $0
        sub(/^package /, "", pkg)
    }
    next
}

function finalize_file(    i, line, in_import, alias, ipath) {
    delete imports
    in_import = 0
    for (i = 1; i <= line_num; i++) {
        line = lines[i]
        if (line ~ /^import[ \t]+\(/) { in_import = 1; continue }
        if (in_import) {
            if (line ~ /^[ \t]*\)/) { in_import = 0; continue }
            if (match(line, /"[^"]+"/)) {
                ipath = substr(line, RSTART + 1, RLENGTH - 2)
                alias = ipath
                sub(/.*\//, "", alias)
                if (match(line, /^[ \t]*[A-Za-z_][A-Za-z0-9_]*[ \t]+"/))
                    alias = substr(line, RSTART, RLENGTH - 2)
                imports[alias] = ipath
            }
            continue
        }
        if (line ~ /^import[ \t]+"/) {
            if (match(line, /"[^"]+"/)) {
                ipath = substr(line, RSTART + 1, RLENGTH - 2)
                alias = ipath
                sub(/.*\//, "", alias)
                imports[alias] = ipath
            }
        }
    }

    file_pkg[curfile] = pkg
    file_dir[curfile] = curfile
    sub(/\/[^\/]+$/, "", file_dir[curfile])

    for (a in imports)
        fi_import[curfile SUBSEP a] = imports[a]

    if (index(curfile, root "/internal/") == 1 && curfile !~ /_test\.go$/) {
        rel = substr(curfile, length(root) + 2)
        np = split(rel, parts, "/")
        import_path = module
        for (i = 1; i < np; i++)
            import_path = import_path "/" parts[i]

        for (i = 1; i <= line_num; i++) {
            line = lines[i]
            if (line ~ /^func[ \t]+/) {
                recv = ""
                fname = ""
                if (match(line, /^func[ \t]+\(/)) {
                    # method
                    tmp = line
                    sub(/^func[ \t]+\(/, "", tmp)
                    if (match(tmp, /^[^)]+\)[ \t]+[A-Za-z_][A-Za-z0-9_]*/)) {
                        chunk = substr(tmp, RSTART, RLENGTH)
                        sub(/^[^(]+\)[ \t]+/, "", chunk)
                        fname = chunk
                        recv = line
                        sub(/^func[ \t]+\(/, "", recv)
                        sub(/\)[ \t]+[A-Za-z_][A-Za-z0-9_]*[ \t]*\(.*$/, "", recv)
                        gsub(/^\*/, "", recv)
                        sub(/^[A-Za-z_][A-Za-z0-9_]*[ \t]+/, "", recv)
                    }
                } else if (match(line, /^func[ \t]+[A-Za-z_][A-Za-z0-9_]*/)) {
                    fname = substr(line, RSTART + 5, RLENGTH - 5)
                    sub(/[ \t]*\(.*$/, "", fname)
                }
                if (fname == "" || fname == "init") continue
                sid = sym_id(import_path, recv, fname)
                decl_path[sid] = curfile
                decl_line[sid] = i
                decl_name[sid] = fname
                decl_recv[sid] = recv
                decl_ip[sid] = import_path
                decl_dir[sid] = file_dir[curfile]
                ndecl++
                dir_decls[file_dir[curfile] SUBSEP sid] = 1
            }
        }
    }

    nf = 0
    for (i = 1; i <= line_num; i++) {
        line = lines[i]
        if (line ~ /^func[ \t]+/) {
            fname = ""
            if (match(line, /^func[ \t]+\(/)) {
                tmp = line
                sub(/^func[ \t]+\([^)]+\)[ \t]+/, "", tmp)
                if (match(tmp, /^[A-Za-z_][A-Za-z0-9_]*/))
                    fname = substr(tmp, RSTART, RLENGTH)
            } else if (match(line, /^func[ \t]+[A-Za-z_][A-Za-z0-9_]*/)) {
                fname = substr(line, RSTART + 5, RLENGTH - 5)
                sub(/[ \t]*\(.*$/, "", fname)
            }
            if (fname != "") {
                nf++
                ff_name[curfile SUBSEP nf] = fname
                ff_start[curfile SUBSEP nf] = i
                brace = 0
                for (j = i; j <= line_num; j++) {
                    ll = lines[j]
                    nk = split(ll, chars, "")
                    for (k = 1; k <= nk; k++) {
                        if (chars[k] == "{") brace++
                        if (chars[k] == "}") brace--
                    }
                    if (j > i && brace <= 0) { ff_end[curfile SUBSEP nf] = j; break }
                }
                if (!((curfile SUBSEP nf) in ff_end)) ff_end[curfile SUBSEP nf] = line_num
            }
        }
    }
    file_nfunc[curfile] = nf

    for (i = 1; i <= line_num; i++)
        file_line[curfile SUBSEP i] = lines[i]
    file_nlines[curfile] = line_num
    filelist[nfiles] = curfile
}

function sym_id(ip, recv, name) {
    if (recv != "") return ip "|(*" recv ")." name
    return ip "|" name
}

function strip_comments(s,    out, idx, in_str, q) {
    out = ""
    in_str = 0
    q = ""
    idx = 1
    while (idx <= length(s)) {
        c = substr(s, idx, 1)
        if (!in_str && substr(s, idx, 2) == "//") break
        if (!in_str && c == "`") {
            in_str = 3
            out = out c
            idx++
            while (idx <= length(s)) {
                c = substr(s, idx, 1)
                out = out c
                idx++
                if (c == "`") { in_str = 0; break }
            }
            continue
        }
        if (!in_str && (c == "\"" || c == "'")) {
            q = c; in_str = 1
            out = out c
            idx++
            while (idx <= length(s)) {
                c = substr(s, idx, 1)
                out = out c
                idx++
                if (c == "\\") { out = out substr(s, idx, 1); idx++; continue }
                if (c == q) { in_str = 0; break }
            }
            continue
        }
        out = out c
        idx++
    }
    return out
}

function record(sid, f, ln, caller) {
    if (!(sid in decl_path)) return
    site_set[sid SUBSEP f ":" ln] = 1
    caller_set[sid SUBSEP f "::" caller] = 1
}

function caller_at(f, ln,    j, n) {
    n = file_nfunc[f] + 0
    for (j = 1; j <= n; j++)
        if (ln >= ff_start[f SUBSEP j] && ln <= ff_end[f SUBSEP j])
            return ff_name[f SUBSEP j]
    return "<toplevel>"
}

function same_pkg(f, d) { return file_dir[f] == d }

function file_imports_path(f, target,    k, kp) {
    for (k in fi_import) {
        split(k, kp, SUBSEP)
        if (kp[1] != f) continue
        if (fi_import[k] == target) return 1
    }
    return 0
}

function is_kw(w) {
    return (w == "break" || w == "case" || w == "chan" || w == "const" || w == "continue" || w == "default" || w == "defer" || w == "else" || w == "fallthrough" || w == "for" || w == "func" || w == "go" || w == "goto" || w == "if" || w == "import" || w == "interface" || w == "map" || w == "package" || w == "range" || w == "return" || w == "select" || w == "struct" || w == "switch" || w == "type" || w == "var")
}

function is_builtin(w) {
    return (w == "append" || w == "cap" || w == "close" || w == "complex" || w == "copy" || w == "delete" || w == "imag" || w == "len" || w == "make" || w == "new" || w == "panic" || w == "print" || w == "println" || w == "real" || w == "recover")
}

function is_bpkg(w) {
    return (w == "fmt" || w == "strings" || w == "strconv" || w == "errors" || w == "context" || w == "time" || w == "io" || w == "os" || w == "log" || w == "sync" || w == "sort" || w == "bytes" || w == "json" || w == "http" || w == "url" || w == "path" || w == "filepath" || w == "reflect" || w == "runtime" || w == "math" || w == "crypto" || w == "net" || w == "sql" || w == "template" || w == "html" || w == "xml" || w == "regexp" || w == "unicode" || w == "bufio" || w == "testing")
}

function find_qualified_calls(code, f, i, caller,    pos, rest, alias, fname, ip, sid) {
    while (match(code, /[A-Za-z_][A-Za-z0-9_]*\.[A-Za-z_][A-Za-z0-9_]*[ \t]*\(/)) {
        chunk = substr(code, RSTART, RLENGTH)
        alias = chunk
        sub(/\.[A-Za-z_][A-Za-z0-9_]*[ \t]*\(.*$/, "", alias)
        fname = chunk
        sub(/^[A-Za-z_][A-Za-z0-9_]*\./, "", fname)
        sub(/[ \t]*\(.*$/, "", fname)
        if (!is_kw(alias) && !is_kw(fname) && !is_bpkg(alias)) {
            ip = fi_import[f SUBSEP alias]
            if (ip != "" && index(ip, module "/internal/") == 1) {
                sid = sym_id(ip, "", fname)
                record(sid, f, i, caller)
            }
        }
        code = substr(code, RSTART + RLENGTH)
    }
}

function find_method_calls(code, f, i, caller,    rest, mname, sid) {
    rest = code
    while (match(rest, /\.[A-Za-z_][A-Za-z0-9_]*[ \t]*\(/)) {
        chunk = substr(rest, RSTART + 1, RLENGTH - 1)
        mname = chunk
        sub(/[ \t]*\(.*$/, "", mname)
        if (!is_kw(mname)) {
            for (sid in decl_path) {
                if (decl_recv[sid] == "" || decl_name[sid] != mname) continue
                if (same_pkg(f, decl_dir[sid]) || file_imports_path(f, decl_ip[sid]))
                    record(sid, f, i, caller)
            }
        }
        rest = substr(rest, RSTART + RLENGTH)
    }
}

function find_bare_calls(code, f, i, caller, cur_dir,    rest, fname, sid, key, kp, a, ip) {
    rest = code
    while (match(rest, /[^A-Za-z0-9_][A-Z][A-Za-z0-9_]*[ \t]*\(/)) {
        fname = substr(rest, RSTART + 1, RLENGTH - 1)
        sub(/[ \t]*\(.*$/, "", fname)
        if (!is_kw(fname) && !is_builtin(fname)) {
            for (key in dir_decls) {
                split(key, kp, SUBSEP)
                if (kp[1] != cur_dir) continue
                sid = kp[2]
                if (decl_recv[sid] != "" || decl_name[sid] != fname) continue
                record(sid, f, i, caller)
            }
            for (a in imports) {
                ip = fi_import[f SUBSEP a]
                if (ip == "" || index(ip, module "/internal/") != 1) continue
                sid = sym_id(ip, "", fname)
                record(sid, f, i, caller)
            }
        }
        rest = substr(rest, RSTART + RLENGTH)
    }
    if (match(code, /^[A-Z][A-Za-z0-9_]*[ \t]*\(/)) {
        fname = code
        sub(/[ \t]*\(.*$/, "", fname)
        if (!is_kw(fname) && !is_builtin(fname)) {
            for (key in dir_decls) {
                split(key, kp, SUBSEP)
                if (kp[1] != cur_dir) continue
                sid = kp[2]
                if (decl_recv[sid] != "" || decl_name[sid] != fname) continue
                record(sid, f, i, caller)
            }
        }
    }
}

END {
    finalize_file()

    for (fi = 1; fi <= nfiles; fi++) {
        f = filelist[fi]
        cur_dir = file_dir[f]
        nlines = file_nlines[f]
        delete imports
        for (k in fi_import) {
            split(k, kp, SUBSEP)
            if (kp[1] == f) imports[kp[2]] = fi_import[k]
        }
        for (i = 1; i <= nlines; i++) {
            line = file_line[f SUBSEP i]
            if (line ~ /^func[ \t]+/) continue
            code = strip_comments(line)
            caller = caller_at(f, i)
            find_qualified_calls(code, f, i, caller)
            find_method_calls(code, f, i, caller)
            find_bare_calls(code, f, i, caller, cur_dir)
        }
    }

    for (sid in decl_path) {
        rank_nc[sid] = 0
        rank_ns[sid] = 0
        for (k in caller_set)
            if (index(k, sid SUBSEP) == 1) rank_nc[sid]++
        for (k in site_set)
            if (index(k, sid SUBSEP) == 1) rank_ns[sid]++
    }

    print "=== INTERNAL DECLARATIONS: " ndecl " ==="
    print ""
    print "=== TOP 30 BY DISTINCT CALLING FUNCTIONS ==="
    for (t = 1; t <= 30; t++) {
        best = ""; bestv = -1; bestns = 0
        for (sid in rank_nc) {
            if (rank_nc[sid] <= 0 || done1[sid]) continue
            if (rank_nc[sid] > bestv || (rank_nc[sid] == bestv && rank_ns[sid] > bestns)) {
                best = sid; bestv = rank_nc[sid]; bestns = rank_ns[sid]
            }
        }
        if (best == "") break
        done1[best] = 1
        sym = decl_name[best]
        if (decl_recv[best] != "") sym = "(*" decl_recv[best] ")." sym
        printf "%3d. %-45s callers=%4d  callsites=%4d\n", t, sym, rank_nc[best], rank_ns[best]
        printf "     %s:%d  [%s]\n", decl_path[best], decl_line[best], decl_ip[best]
    }

    print ""
    print "=== TOP 30 BY CALL SITES ==="
    for (t = 1; t <= 30; t++) {
        best = ""; bestv = -1; bestnc = 0
        for (sid in rank_ns) {
            if (rank_ns[sid] <= 0 || done2[sid]) continue
            if (rank_ns[sid] > bestv || (rank_ns[sid] == bestv && rank_nc[sid] > bestnc)) {
                best = sid; bestv = rank_ns[sid]; bestnc = rank_nc[sid]
            }
        }
        if (best == "") break
        done2[best] = 1
        sym = decl_name[best]
        if (decl_recv[best] != "") sym = "(*" decl_recv[best] ")." sym
        printf "%3d. %-45s callsites=%4d  callers=%4d\n", t, sym, rank_ns[best], rank_nc[best]
        printf "     %s:%d\n", decl_path[best], decl_line[best]
    }

    top = ""; topv = -1
    for (sid in rank_nc)
        if (rank_nc[sid] > topv) { top = sid; topv = rank_nc[sid] }
    if (top != "") {
        sym = decl_name[top]
        if (decl_recv[top] != "") sym = "(*" decl_recv[top] ")." sym
        print ""
        print "=== TOP BY CALLERS DETAIL ==="
        print "Symbol: " sym
        print "Path: " decl_path[top] ":" decl_line[top]
        print "Distinct callers: " rank_nc[top]
        print "Call sites: " rank_ns[top]
        print "Callers:"
        for (k in caller_set) {
            if (index(k, top SUBSEP) != 1) continue
            sub("^" top SUBSEP, "", k)
            print "  " k
        }
        print "Sites:"
        for (k in site_set) {
            if (index(k, top SUBSEP) != 1) continue
            sub("^" top SUBSEP, "", k)
            print "  " k
        }
    }
}

