success.afterFullFileContent:
BEGIN {
    root = ENVIRON["ROOT"]
    module = ENVIRON["MODULE"]
    nfiles = 0
    ndecl = 0
}

/^FILE / {
    if (nfiles > 0) finalize_file()
    curfile = substr($0, 6)
    nfiles++
    pkg = ""
    line_num = 0
    next
}

/^ENDFILE$/ {
    finalize_file()
    next
}

{
    line_num++
    lines[line_num] = $0
    if (pkg == "" && $0 ~ /^package [A-Za-z_]/) {
        pkg = $0
        sub(/^package /, "", pkg)
    }
    next
}

function finalize_file(    i, line, in_import, alias, ipath) {
    delete imports
    in_import = 0
    for (i = 1; i <= line_num; i++) {
        line = lines[i]
        if (line ~ /^import[ \t]+\(/) { in_import = 1; continue }
        if (in_import) {
            if (line ~ /^[ \t]*\)/) { in_import = 0; continue }
            if (match(line, /"[^"]+"/)) {
                ipath = substr(line, RSTART + 1, RLENGTH - 2)
                alias = ipath
                sub(/.*\//, "", alias)
                if (match(line, /^[ \t]*[A-Za-z_][A-Za-z0-9_]*[ \t]+"/))
                    alias = substr(line, RSTART, RLENGTH - 2)
                imports[alias] = ipath
            }
            continue
        }
        if (line ~ /^import[ \t]+"/) {
            if (match(line, /"[^"]+"/)) {
                ipath = substr(line, RSTART + 1, RLENGTH - 2)
                alias = ipath
                sub(/.*\//, "", alias)
                imports[alias] = ipath
            }
        }
    }

    file_pkg[curfile] = pkg
    file_dir[curfile] = curfile
    sub(/\/[^\/]+$/, "", file_dir[curfile])

    for (a in imports)
        fi_import[curfile SUBSEP a] = imports[a]

    if (index(curfile, root "/internal/") == 1 && curfile !~ /_test\.go$/) {
        rel = substr(curfile, length(root) + 2)
        np = split(rel, parts, "/")
        import_path = module
        for (i = 1; i < np; i++)
            import_path = import_path "/" parts[i]

        for (i = 1; i <= line_num; i++) {
            line = lines[i]
            if (line ~ /^func[ \t]+/) {
                recv = ""
                fname = ""
                if (match(line, /^func[ \t]+\(/)) {
                    # method
                    tmp = line
                    sub(/^func[ \t]+\(/, "", tmp)
                    if (match(tmp, /^[^)]+\)[ \t]+[A-Za-z_][A-Za-z0-9_]*/)) {
                        chunk = substr(tmp, RSTART, RLENGTH)
                        sub(/^[^(]+\)[ \t]+/, "", chunk)
                        fname = chunk
                        recv = line
                        sub(/^func[ \t]+\(/, "", recv)
                        sub(/\)[ \t]+[A-Za-z_][A-Za-z0-9_]*[ \t]*\(.*$/, "", recv)
                        gsub(/^\*/, "", recv)
                        sub(/^[A-Za-z_][A-Za-z0-9_]*[ \t]+/, "", recv)
                    }
                } else if (match(line, /^func[ \t]+[A-Za-z_][A-Za-z0-9_]*/)) {
                    fname = substr(line, RSTART + 5, RLENGTH - 5)
                    sub(/[ \t]*\(.*$/, "", fname)
                }
                if (fname == "" || fname == "init") continue
                sid = sym_id(import_path, recv, fname)
                decl_path[sid] = curfile
                decl_line[sid] = i
                decl_name[sid] = fname
                decl_recv[sid] = recv
                decl_ip[sid] = import_path
                decl_dir[sid] = file_dir[curfile]
                ndecl++
                dir_decls[file_dir[curfile] SUBSEP sid] = 1
            }
        }
    }

    nf = 0
    for (i = 1; i <= line_num; i++) {
        line = lines[i]
        if (line ~ /^func[ \t]+/) {
            fname = ""
            if (match(line, /^func[ \t]+\(/)) {
                tmp = line
                sub(/^func[ \t]+\([^)]+\)[ \t]+/, "", tmp)
                if (match(tmp, /^[A-Za-z_][A-Za-z0-9_]*/))
                    fname = substr(tmp, RSTART, RLENGTH)
            } else if (match(line, /^func[ \t]+[A-Za-z_][A-Za-z0-9_]*/)) {
                fname = substr(line, RSTART + 5, RLENGTH - 5)
                sub(/[ \t]*\(.*$/, "", fname)
            }
            if (fname != "") {
                nf++
                ff_name[curfile SUBSEP nf] = fname
                ff_start[curfile SUBSEP nf] = i
                brace = 0
                for (j = i; j <= line_num; j++) {
                    ll = lines[j]
                    nk = split(ll, chars, "")
                    for (k = 1; k <= nk; k++) {
                        if (chars[k] == "{") brace++
                        if (chars[k] == "}") brace--
                    }
                    if (j > i && brace <= 0) { ff_end[curfile SUBSEP nf] = j; break }
                }
                if (!((curfile SUBSEP nf) in ff_end)) ff_end[curfile SUBSEP nf] = line_num
            }
        }
    }
    file_nfunc[curfile] = nf

    for (i = 1; i <= line_num; i++)
        file_line[curfile SUBSEP i] = lines[i]
    file_nlines[curfile] = line_num
    filelist[nfiles] = curfile
}

