        }
        if (!in_str && (c == "\"" || c == "'")) {
            q = c; in_str = 1
            out = out c
            idx++
            while (idx <= length(s)) {
                c = substr(s, idx, 1)
                out = out c
                idx++
                if (c == "\\") { out = out substr(s, idx, 1); idx++; continue }
                if (c == q) { in_str = 0; break }
