#!/bin/bash
set -euo pipefail
ROOT="/bench/repo"
MODULE="github.com/usememos/memos"

# Phase 1: extract internal declarations -> sid, path, line, name, recv, import_path, dir
DECL=/tmp/fanin_decl.tsv
: > "$DECL"

while IFS= read -r f; do
  [[ "$f" == *"_test.go" ]] && continue
  [[ "$f" != "$ROOT/internal/"* ]] && continue
  rel="${f#$ROOT/}"
  ip="$MODULE/${rel%/*}"
  dir="${f%/*}"
  pkg=$(grep -m1 '^package ' "$f" | awk '{print $2}' | sed 's/\/\/.*//')
  lineno=0
  while IFS= read -r line; do
    ((lineno++)) || true
    [[ "$line" =~ ^func[[:space:]] ]] || continue
    recv=""
    fname=""
    if [[ "$line" =~ ^func[[:space:]]+\(([^)]*)\)[[:space:]]+([A-Za-z_][A-Za-z0-9_]*)[[:space:]]*\( ]]; then
      recv="${BASH_REMATCH[1]}"
      fname="${BASH_REMATCH[2]}"
      recv="${recv#\*}"
      recv="$(echo "$recv" | awk '{print $NF}')"
    elif [[ "$line" =~ ^func[[:space:]]+([A-Za-z_][A-Za-z0-9_]*)[[:space:]]*\( ]]; then
      fname="${BASH_REMATCH[1]}"
    else
      continue
    fi
    [[ "$fname" == "init" ]] && continue
    if [[ -n "$recv" ]]; then
      sid="${ip}|(*${recv}).${fname}"
    else
      sid="${ip}|${fname}"
    fi
    printf '%s\t%s\t%d\t%s\t%s\t%s\t%s\n' "$sid" "$f" "$lineno" "$fname" "$recv" "$ip" "$dir"
  done < "$f"
done < <(find "$ROOT" -name '*.go' | sort) >> "$DECL"

echo "Declarations: $(wc -l < "$DECL")"

# Phase 2: build import map per file: file\talias\timport_path
IMPORTS=/tmp/fanin_imports.tsv
: > "$IMPORTS"
while IFS= read -r f; do
  awk -v file="$f" '
    BEGIN { inblock=0 }
    /^import[ \t]+\(/ { inblock=1; next }
    inblock && /^[ \t]*\)/ { inblock=0; next }
    inblock && /"/ {
      line=$0; sub(/\/\/.*$/,"",line)
      alias=""; path=""
      if (match(line, /"[^"]+"/)) { path=substr(line,RSTART+1,RLENGTH-2) }
      if (match(line, /^[ \t]*[A-Za-z_][A-Za-z0-9_]*[ \t]+"/))
        alias=substr(line,RSTART,RLENGTH-2)
      if (alias=="") { alias=path; sub(/.*\//,"",alias) }
      if (path!="") printf "%s\t%s\t%s\n", file, alias, path
      next
    }
    /^import[ \t]+"/ {
      line=$0
      if (match(line, /"[^"]+"/)) {
        path=substr(line,RSTART+1,RLENGTH-2)
        alias=path; sub(/.*\//,"",alias)
        printf "%s\t%s\t%s\n", file, alias, path
      }
    }
  ' "$f"
done < <(find "$ROOT" -name '*.go' | sort) >> "$IMPORTS"

# Phase 3: caller function ranges per file
CALLERS=/tmp/fanin_func_ranges.tsv
: > "$CALLERS"
while IFS= read -r f; do
  awk -v file="$f" '
    /^func / {
      name=$0; sub(/^func /,"",name)
      if (match(name, /^\([^)]+\)[ \t]+/)) name=substr(name,RSTART+RLENGTH)
      sub(/[ \t]*\(.*$/,"",name)
      start=NR; brace=0; end=NR
      for (j=NR; j<=FNR+100000; j++) { }
    }
    BEGIN { }
    {
      if ($0 ~ /^func /) {
        fname=$0; sub(/^func /,"",fname)
        if (match(fname, /^\([^)]+\)[ \t]+/)) fname=substr(fname,RSTART+RLENGTH)
        sub(/[ \t]*\(.*$/,"",fname)
        fstart=NR; brace=0
        for (j=NR; j<=999999; j++) {
          getline l < FILENAME
          # cannot getline forward easily
        }
      }
    }
  ' "$f" 2>/dev/null || true
done

# Use awk for pass 3+4 in one shot
awk -F'\t' -v root="$ROOT" -v module="$MODULE" '
BEGIN {
  while ((getline line < "/tmp/fanin_decl.tsv") > 0) {
    split(line, a, "\t")
    sid=a[1]; decl_path[sid]=a[2]; decl_line[sid]=a[3]+0
    decl_name[sid]=a[4]; decl_recv[sid]=a[5]; decl_ip[sid]=a[6]; decl_dir[sid]=a[7]
    dir_decls[a[7] SUBSEP sid]=1
    ndecl++
  }
  close("/tmp/fanin_decl.tsv")
  while ((getline line < "/tmp/fanin_imports.tsv") > 0) {
    split(line, a, "\t")
    fi_import[a[1] SUBSEP a[2]]=a[3]
  }
  close("/tmp/fanin_imports.tsv")
}

function sym_id(ip, recv, name) {
  if (recv != "") return ip "|(*" recv ")." name
  return ip "|" name
}

function load_file_funcs(f,    cmd, fn, fs, fe) {
  cmd = "awk -v file=\"" f "\" \047/^func / { n=$0; sub(/^func /,\"\",n); if (match(n,/^\\([^)]+\\)[ \\t]+/)) n=substr(n,RSTART+RLENGTH); sub(/[ \\t]*\\(.*$/,\"\",n); print file \"\\t\" n \"\\t\" NR }\047 \"" f "\""
  # skip - build inline below
}

function caller_of(f, ln,    i, n, k) {
  n = fn_n[f]+0
  for (i=1; i<=n; i++) {
    if (ln >= fn_start[f SUBSEP i] && ln <= fn_end[f SUBSEP i]) return fn_name[f SUBSEP i]
  }
  return "<toplevel>"
}

function record(sid, f, ln, caller) {
  if (!(sid in decl_path)) return
  site[sid SUBSEP f ":" ln]=1
  callers[sid SUBSEP f "::" caller]=1
}

function strip(s,    i,c,out,inbt) {
  out=""; inbt=0
  for (i=1;i<=length(s);i++) {
    c=substr(s,i,1)
    if (!inbt && substr(s,i,2)=="//") break
    if (c=="`") {
      if (!inbt) inbt=1; else inbt=0
      continue
    }
    if (!inbt && c=="\"") {
      i++
      while (i<=length(s)) { c=substr(s,i,1); if (c=="\\") { i+=2; continue } if (c=="\"") break; i++ }
      continue
    }
    out=out c
  }
  return out
}

function is_kw(w) {
  return w=="break"||w=="case"||w=="chan"||w=="const"||w=="continue"||w=="default"||w=="defer"||w=="else"||w=="fallthrough"||w=="for"||w=="func"||w=="go"||w=="goto"||w=="if"||w=="import"||w=="interface"||w=="map"||w=="package"||w=="range"||w=="return"||w=="select"||w=="struct"||w=="switch"||w=="type"||w=="var"
}
function is_builtin(w) {
  return w=="append"||w=="cap"||w=="close"||w=="complex"||w=="copy"||w=="delete"||w=="imag"||w=="len"||w=="make"||w=="new"||w=="panic"||w=="print"||w=="println"||w=="real"||w=="recover"
}
function is_bpkg(w) {
  return w=="fmt"||w=="strings"||w=="strconv"||w=="errors"||w=="context"||w=="time"||w=="io"||w=="os"||w=="log"||w=="sync"||w=="sort"||w=="bytes"||w=="json"||w=="http"||w=="url"||w=="path"||w=="filepath"||w=="reflect"||w=="runtime"||w=="math"||w=="crypto"||w=="net"||w=="sql"||w=="template"||w=="html"||w=="xml"||w=="regexp"||w=="unicode"||w=="bufio"||w=="testing"
}
function imports_path(f, target,    k, kp) {
  for (k in fi_import) {
    split(k, kp, SUBSEP); if (kp[1]!=f) continue
    if (fi_import[k]==target) return 1
  }
  return 0
}
function file_dir(f) { d=f; sub(/\/[^\/]+$/,"",d); return d }

function scan_calls(f,    ln, line, code, caller, cur_dir, rest, alias, fname, ip, sid, mname, key, kp, a) {
  cur_dir = file_dir(f)
  while ((getline line < f) > 0) {
    ln++
    if (line ~ /^func /) continue
    code = strip(line)
    caller = caller_of(f, ln)
    rest = code
    while (match(rest, /[A-Za-z_][A-Za-z0-9_]*\.[A-Za-z_][A-Za-z0-9_]*[ \t]*\(/)) {
      chunk = substr(rest, RSTART, RLENGTH)
