    decl_ip[sid]=a[6]; decl_dir[sid]=a[7]
    dir_decls[a[7] SUBSEP sid]=1
    ndecl++
  }
  close("/tmp/fanin_decl.tsv")
  while ((getline line < "/tmp/fanin_imports.tsv") > 0) {
    split(line, a, "\t")
    fi_import[a[1] SUBSEP a[2]]=a[3]
  }
  close("/tmp/fanin_imports.tsv")
}

function sym_id(ip, recv, name) {
  if (recv != "") return ip "|(*" recv ")." name
  return ip "|" name
}

function file_dir(f, d) { d=f; sub(/\/[^\/]+$/,"",d); return d }

function is_kw(w) {
  return w=="break"||w=="case"||w=="chan"||w=="const"||w=="continue"||w=="default"||w=="defer"||w=="else"||w=="fallthrough"||w=="for"||w=="func"||w=="go"||w=="goto"||w=="if"||w=="import"||w=="interface"||w=="map"||w=="package"||w=="range"||w=="return"||w=="select"||w=="struct"||w=="switch"||w=="type"||w=="var"
}
function is_builtin(w) {
  return w=="append"||w=="cap"||w=="close"||w=="complex"||w=="copy"||w=="delete"||w=="imag"||w=="len"||w=="make"||w=="new"||w=="panic"||w=="print"||w=="println"||w=="real"||w=="recover"
}
function is_bpkg(w) {
  return w=="fmt"||w=="strings"||w=="strconv"||w=="errors"||w=="context"||w=="time"||w=="io"||w=="os"||w=="log"||w=="sync"||w=="sort"||w=="bytes"||w=="json"||w=="http"||w=="url"||w=="path"||w=="filepath"||w=="reflect"||w=="runtime"||w=="math"||w=="crypto"||w=="net"||w=="sql"||w=="template"||w=="html"||w=="xml"||w=="regexp"||w=="unicode"||w=="bufio"||w=="testing"
}

function imports_path(f, target, k, kp) {
  for (k in fi_import) {
    split(k, kp, SUBSEP)
    if (kp[1] != f) continue
    if (fi_import[k] == target) return 1
  }
  return 0
}

function strip(s, i, c, out, inbt) {
  out = ""
  inbt = 0
  for (i = 1; i <= length(s); i++) {
    c = substr(s, i, 1)
    if (!inbt && substr(s, i, 2) == "//") break
    if (c == "`") { inbt = !inbt; continue }
    if (!inbt && c == "\"") {
      i++
      while (i <= length(s)) {
        c = substr(s, i, 1)
        if (c == "\\") { i += 2; continue }
        if (c == "\"") break
        i++
      }
      continue
    }
    out = out c
  }
  return out
}

function record(sid, f, ln, caller) {
  if (!(sid in decl_path)) return
  site[sid SUBSEP f ":" ln] = 1
  callers[sid SUBSEP f "::" caller] = 1
}

function build_func_ranges(f,    ln, line, n, fname, brace, j, ll, k, nk, chars) {
  n = 0; ln = 0
  while ((getline line < f) > 0) {
    ln++
    flines[ln] = line
  }
  close(f)
  fnlines[f] = ln
  for (i = 1; i <= ln; i++) {
    line = flines[i]
    if (line !~ /^func /) continue
    fname = line
    sub(/^func /, "", fname)
    if (match(fname, /^\([^)]+\)[ \t]+/)) fname = substr(fname, RSTART + RLENGTH)
    sub(/[ \t]*\(.*$/, "", fname)
    n++
    fn_name[f SUBSEP n] = fname
    fn_start[f SUBSEP n] = i
    brace = 0
    for (j = i; j <= ln; j++) {
      ll = flines[j]
      nk = split(ll, chars, "")
      for (k = 1; k <= nk; k++) {
        if (chars[k] == "{") brace++
        if (chars[k] == "}") brace--
      }
      if (j > i && brace <= 0) { fn_end[f SUBSEP n] = j; break }
    }
    if (!((f SUBSEP n) in fn_end)) fn_end[f SUBSEP n] = ln
  }
  fn_n[f] = n
  delete flines
}

function caller_of(f, ln, j, n) {
  n = fn_n[f] + 0
  for (j = 1; j <= n; j++)
    if (ln >= fn_start[f SUBSEP j] && ln <= fn_end[f SUBSEP j])
      return fn_name[f SUBSEP j]
  return "<toplevel>"
}

function scan_file(f,    ln, line, code, caller, cur_dir, rest, alias, fname, ip, sid, mname, key, kp, k) {
  build_func_ranges(f)
  cur_dir = file_dir(f)
  for (ln = 1; ln <= fnlines[f]; ln++) {
    line = ""
    # re-read from stored - rebuild needed
  }
  # read again
  while ((getline line < f) > 0) {
    ln++
    if (line ~ /^func /) continue
    code = strip(line)
    caller = caller_of(f, ln)

    rest = code
    while (match(rest, /[A-Za-z_][A-Za-z0-9_]*\.[A-Za-z_][A-Za-z0-9_]*[ \t]*\(/)) {
      chunk = substr(rest, RSTART, RLENGTH)
      alias = chunk; sub(/\.[A-Za-z_][A-Za-z0-9_]*[ \t]*\(.*$/, "", alias)
      fname = chunk; sub(/^[A-Za-z_][A-Za-z0-9_]*\./, "", fname); sub(/[ \t]*\(.*$/, "", fname)
      if (!is_kw(alias) && !is_kw(fname) && !is_bpkg(alias)) {
        ip = fi_import[f SUBSEP alias]
        if (ip != "" && index(ip, module "/internal/") == 1)
          record(sym_id(ip, "", fname), f, ln, caller)
      }
      rest = substr(rest, RSTART + RLENGTH)
    }

    rest = code
    while (match(rest, /\.[A-Za-z_][A-Za-z0-9_]*[ \t]*\(/)) {
      mname = substr(rest, RSTART + 1, RLENGTH - 1); sub(/[ \t]*\(.*$/, "", mname)
      if (!is_kw(mname)) {
        for (sid in decl_path) {
          if (decl_recv[sid] == "" || decl_name[sid] != mname) continue
          if (cur_dir == decl_dir[sid] || imports_path(f, decl_ip[sid]))
            record(sid, f, ln, caller)
        }
      }
      rest = substr(rest, RSTART + RLENGTH)
    }

    rest = code
    while (match(rest, /[^A-Za-z0-9_][A-Z][A-Za-z0-9_]*[ \t]*\(/)) {
      fname = substr(rest, RSTART + 1, RLENGTH - 1); sub(/[ \t]*\(.*$/, "", fname)
      if (!is_kw(fname) && !is_builtin(fname)) {
        for (key in dir_decls) {
          split(key, kp, SUBSEP)
          if (kp[1] != cur_dir) continue
          sid = kp[2]
          if (decl_recv[sid] != "" || decl_name[sid] != fname) continue
          record(sid, f, ln, caller)
        }
        for (k in fi_import) {
          split(k, kp, SUBSEP)
          if (kp[1] != f) continue
          ip = fi_import[k]
          if (index(ip, module "/internal/") != 1) continue
          record(sym_id(ip, "", fname), f, ln, caller)
        }
      }
      rest = substr(rest, RSTART + RLENGTH)
    }
    if (match(code, /^[A-Z][A-Za-z0-9_]*[ \t]*\(/)) {
      fname = code; sub(/[ \t]*\(.*$/, "", fname)
      if (!is_kw(fname) && !is_builtin(fname)) {
        for (key in dir_decls) {
          split(key, kp, SUBSEP)
          if (kp[1] != cur_dir) continue
          sid = kp[2]
          if (decl_recv[sid] != "" || decl_name[sid] != fname) continue
          record(sid, f, ln, caller)
        }
      }
    }
  }
  close(f)
}

FNR == 1 && NR > 1 { scan_file(prev); prev = FILENAME; next }
FNR == 1 { prev = FILENAME; next }
{ next }

END {
  if (prev != "") scan_file(prev)

  for (sid in decl_path) {
    rank_nc[sid] = 0; rank_ns[sid] = 0
    for (k in callers) if (index(k, sid SUBSEP) == 1) rank_nc[sid]++
    for (k in site) if (index(k, sid SUBSEP) == 1) rank_ns[sid]++
  }

  print "=== INTERNAL DECLARATIONS: " ndecl " ==="
  print ""
  print "=== TOP 30 BY DISTINCT CALLING FUNCTIONS (fan-in) ==="
  for (t = 1; t <= 30; t++) {
    best = ""; bestv = -1; bestns = 0
    for (sid in rank_nc) {
      if (rank_nc[sid] <= 0 || done1[sid]) continue
      if (rank_nc[sid] > bestv || (rank_nc[sid] == bestv && rank_ns[sid] > bestns)) {
        best = sid; bestv = rank_nc[sid]; bestns = rank_ns[sid]
      }
    }
    if (best == "") break
    done1[best] = 1
    sym = decl_name[best]
    if (decl_recv[best] != "") sym = "(*" decl_recv[best] ")." sym
    printf "%3d. %-45s callers=%4d  callsites=%4d\n", t, sym, rank_nc[best], rank_ns[best]
    printf "     %s:%d  [%s]\n", decl_path[best], decl_line[best], decl_ip[best]
  }

  print ""
  print "=== TOP 10 BY CALL SITES ==="
  for (t = 1; t <= 10; t++) {
    best = ""; bestv = -1
    for (sid in rank_ns) {
      if (rank_ns[sid] <= 0 || done2[sid]) continue
      if (rank_ns[sid] > bestv) { best = sid; bestv = rank_ns[sid] }
    }
    if (best == "") break
    done2[best] = 1
    sym = decl_name[best]
    if (decl_recv[best] != "") sym = "(*" decl_recv[best] ")." sym
    printf "%3d. %-45s callsites=%4d  callers=%4d\n", t, sym, rank_ns[best], rank_nc[best]
    printf "     %s:%d\n", decl_path[best], decl_line[best]
  }

  top = ""; topv = -1
  for (sid in rank_nc) if (rank_nc[sid] > topv) { top = sid; topv = rank_nc[sid] }
  if (top != "") {
    sym = decl_name[top]
    if (decl_recv[top] != "") sym = "(*" decl_recv[top] ")." sym
    print ""
    print "=== TOP SYMBOL DETAIL ==="
    print "Symbol: " sym
    print "Declaration: " decl_path[top] ":" decl_line[top]
    print "Import path: " decl_ip[top]
    print "Distinct calling functions: " rank_nc[top]
    print "Distinct call sites: " rank_ns[top]
    print "Callers:"
    for (k in callers) {
      if (index(k, top SUBSEP) != 1) continue
      sub("^" top SUBSEP, "", k)
      print "  " k
    }
    print "Call sites:"
    for (k in site) {
      if (index(k, top SUBSEP) != 1) continue
      sub("^" top SUBSEP, "", k)
      print "  " k
    }
  }
}

